/* ------------------------------ Aides de saisie ------------------------------ */

/** Postes d'activation (clé `activation_cost_items` → catégorie budgétaire du poste). */
const A = {
  lieu: (share: number, label = "Location du lieu"): TemplateLine => ({ label, category: "EVENEMENT", costItem: "LIEU", share }),
  traiteur: (share: number, label = "Traiteur / restauration"): TemplateLine => ({ label, category: "EVENEMENT", costItem: "TRAITEUR", share }),
  materiel: (share: number, label = "Matériel / stand"): TemplateLine => ({ label, category: "EVENEMENT", costItem: "MATERIEL", share }),
  impression: (share: number, label = "Branding / PLV imprimée"): TemplateLine => ({ label, category: "PLV", costItem: "IMPRESSION", share }),
  transport: (share: number, label = "Transport / logistique"): TemplateLine => ({ label, category: "AUTRES", costItem: "TRANSPORT", share }),
  cachet: (share: number, label = "Cachet intervenant"): TemplateLine => ({ label, category: "PRESCRIPTEURS", costItem: "CACHET", share }),
  echantillons: (share: number, label = "Sampling / échantillons"): TemplateLine => ({ label, category: "ECHANTILLONS", costItem: "ECHANTILLONS", share }),
  goodies: (share: number, label = "Goodies / cadeaux"): TemplateLine => ({ label, category: "GOODIES", costItem: "GOODIES", share }),
  hotesses: (share: number, label = "Animation / hôtesses"): TemplateLine => ({ label, category: "ANIMATION", costItem: "HOTESSES", share }),
  sponsoring: (share: number, label = "Emplacement / droits"): TemplateLine => ({ label, category: "SPONSORING", costItem: "SPONSORING", share }),
  communication: (share: number, label = "Création de contenu / relais"): TemplateLine => ({ label, category: "DIGITAL", costItem: "COMMUNICATION", share }),
  imprevus: (share = 0.08): TemplateLine => ({ label: "Imprévus", category: "AUTRES", costItem: "AUTRE", share }),
};

/** Postes de campagne (catégorie budgétaire seule). */
const C = (label: string, category: BudgetCategory, share: number): TemplateLine => ({ label, category, share });
const IMPREVUS = (share = 0.08): TemplateLine => ({ label: "Imprévus", category: "AUTRES", share });

const S = (offset: number, label: string, role: StepRole = "MARKETING"): TemplateStep => ({ offset, label, role });

